import requests
import pandas as pd
import os

urls = {
    "imf_weo.xlsx": "https://www.imf.org/-/media/Files/Publications/WEO/WEO-Database/WEOhistorical.ashx",
    "pwt_wilde.xlsx": "https://raw.githubusercontent.com/joshua-wilde/pwt10/master/pwt1001.xlsx"
}

for name, url in urls.items():
    print(f"Downloading {name} from {url}...")
    try:
        r = requests.get(url, allow_redirects=True)
        r.raise_for_status()
        with open(name, "wb") as f:
            f.write(r.content)
        print(f"{name} downloaded. Size: {len(r.content)} bytes")
    except Exception as e:
        print(f"Error downloading {name}: {e}")

# Inspect IMF
try:
    print("\n--- IMF Inspection ---")
    # It might be xls or xlsx
    try:
        df = pd.read_excel("imf_weo.xlsx", nrows=5)
    except:
         # Try reading as CSV if excel fails, sometimes .ashx is just a wrapper
        df = pd.read_csv("imf_weo.xlsx", sep="\t", encoding="latin1", nrows=5)
    print(df.columns.tolist())
except Exception as e:
    print(f"IMF Read Error: {e}")

# Inspect PWT
try:
    print("\n--- PWT Inspection ---")
    df = pd.read_excel("pwt_wilde.xlsx", sheet_name="Data", nrows=5)
    print(df.columns.tolist())
except Exception as e:
    print(f"PWT Read Error: {e}")

